import type { BankQuestion } from "@/lib/bank";

/** Profit and Loss (Quantitative Aptitude): 143 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-profit-loss-1","question":"An article bought for ₹500 is sold for ₹600. The profit percentage is:","options":["10%","16.67%","20%","25%"],"answer":2,"explanation":"Profit = ₹100; profit % = 100 / 500 × 100 = 20%.","difficulty":"moderate"},
  {"id":"quant-profit-loss-2","question":"Profit and loss percentages are always calculated on the:","options":["Selling price","Marked price","Cost price","Discount"],"answer":2,"explanation":"Unless stated otherwise, profit % and loss % are on the cost price.","difficulty":"easy"},
  {"id":"quant-profit-loss-3","question":"A shopkeeper allows a 10% discount on a marked price of ₹800. The selling price is:","options":["₹700","₹720","₹780","₹790"],"answer":1,"explanation":"Discount = 10% of 800 = ₹80, so SP = ₹720.","difficulty":"moderate"},
  {"id":"quant-profit-loss-4","question":"The cost price of 20 articles equals the selling price of 16 articles. The profit percentage is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"Let CP of each article be ₹1: CP = 20, SP of 16 = 20, so SP of each = 1.25. Profit = 25%.","difficulty":"very-hard"},
  {"id":"quant-profit-loss-5","question":"An article bought for ₹400 is sold for ₹500. The profit percent is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"Profit = 100 on CP 400 ⇒ 25%.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-profit-loss-6","question":"A shopkeeper marks an article 40% above cost and gives a 20% discount. His profit percent is:","options":["12%","16%","20%","24%"],"answer":0,"explanation":"SP = 1.4 × 0.8 = 1.12 × CP ⇒ 12% profit.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-7","question":"The cost price of 20 articles equals the selling price of 16 articles. The gain percent is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"SP/CP per article = 20/16 = 1.25 ⇒ 25% gain.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-profit-loss-8","question":"A dishonest dealer sells at cost price but uses a weight of 800 g for 1 kg. His gain percent is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"Gain = error/(true − error) = 200/800 = 25%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-profit-loss-9","question":"An article is sold for ₹414 at a loss of 8%. Its cost price is:","options":["₹450","₹460","₹380","₹447"],"answer":0,"explanation":"SP = 92% of CP, so CP = 414/0.92 = ₹450. Adding 8% of 414 (₹447) is the wrong-base slip.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-10","question":"The marked price of a shirt is ₹1,200 and a 15% discount is allowed. The selling price is:","options":["₹1,020","₹1,000","₹1,050","₹1,080"],"answer":0,"explanation":"Discount = 15% of 1,200 = ₹180, so SP = 1,200 − 180 = ₹1,020.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-profit-loss-11","question":"A trader sells an article at a loss of 20%. Had he sold it for ₹200 more, he would have gained 5%. The cost price is:","options":["₹1,000","₹800","₹600","₹750"],"answer":1,"explanation":"The two selling prices differ by 20% + 5% = 25% of CP = ₹200, so CP = ₹800.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-12","question":"By selling a watch for ₹1,080 a dealer gains 20%. To gain 25% he should sell it for:","options":["₹1,100","₹1,350","₹1,125","₹1,150"],"answer":2,"explanation":"CP = 1,080/1.2 = ₹900; 125% of 900 = ₹1,125. Adding 5% of 1,080 gives the wrong ₹1,134.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-13","question":"Two articles are sold for ₹1,200 each, one at a profit of 20% and the other at a loss of 20%. The overall result is:","options":["₹100 profit","no profit, no loss","₹96 loss","₹100 loss"],"answer":3,"explanation":"CP₁ = 1,200/1.2 = ₹1,000 and CP₂ = 1,200/0.8 = ₹1,500. Total CP ₹2,500, total SP ₹2,400: a loss of ₹100 (4% of CP). Equal SPs with equal percent gain and loss always give a loss.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-14","question":"Successive discounts of 20% and 10% are given on a marked price of ₹500. The selling price is:","options":["₹370","₹400","₹350","₹360"],"answer":3,"explanation":"SP = 500 × 0.8 × 0.9 = ₹360. Adding the discounts to 30% gives the wrong ₹350.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-profit-loss-15","question":"A shopkeeper marks his goods 50% above cost price, allows a 20% discount and also uses a 900 g weight in place of 1 kg. His profit percent is:","options":["25%","30%","20%","33⅓%"],"answer":3,"explanation":"Per kg price charged = 1.5 × 0.8 = 1.2 × CP of 1 kg, but he gives only 0.9 kg costing 0.9 CP. Profit = (1.2 − 0.9)/0.9 = 1/3 = 33⅓%. Ignoring the false weight gives 20%.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-16","question":"A retailer buys goods at a 20% discount on the list price and sells them at 10% above the list price. His profit percent is:","options":["40%","30%","37.5%","32%"],"answer":2,"explanation":"Take list price 100: CP = 80, SP = 110, profit = 30 on 80 = 37.5%. Taking 30 on 100 gives the wrong 30%.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-17","question":"A dealer sells an article at 10% profit. Had he bought it for 10% less and sold it for ₹14 more, his profit would have been 25%. The cost price is:","options":["₹640","₹500","₹600","₹560"],"answer":3,"explanation":"Let CP = x: SP = 1.1x. New CP = 0.9x, new SP = 1.25 × 0.9x = 1.125x. So 1.125x − 1.1x = 14, 0.025x = 14, x = ₹560. Check: 504 × 1.25 = 630 = 616 + 14.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-18","question":"A shopkeeper marks his goods so that even after allowing a 25% discount he gains 20%. The marked price is above the cost price by:","options":["55%","45%","60%","50%"],"answer":2,"explanation":"0.75 × MP = 1.2 × CP, so MP = 1.6 CP, i.e. 60% above cost. Adding 25% + 20% = 45% is the slip.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-19","question":"The profit earned by selling an article for ₹1,440 equals the loss incurred by selling it for ₹1,200. To gain 15% it should be sold for:","options":["₹1,480","₹1,560","₹1,500","₹1,518"],"answer":3,"explanation":"CP is midway: (1,440 + 1,200)/2 = ₹1,320. SP for 15% gain = 1.15 × 1,320 = ₹1,518.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-profit-loss-20","question":"A fruit seller buys oranges at 5 for ₹4 and sells them at 4 for ₹5. His gain percent is:","options":["25%","50%","56.25%","60%"],"answer":2,"explanation":"CP per orange = ₹0.80, SP = ₹1.25. Gain = 0.45/0.80 = 56.25%. The naive 25% (5 vs 4) ignores that the base is the cost.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-profit-loss-21","question":"Three successive discounts of 10%, 20% and 25% are equivalent to a single discount of:","options":["50%","46%","55%","54%"],"answer":1,"explanation":"Net price factor = 0.9 × 0.8 × 0.75 = 0.54, so the single discount = 1 − 0.54 = 46%. 54% is what remains, not the discount; 55% is the sum.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-22","question":"A dealer buys 100 kg of potatoes at ₹40 per kg. 20% of the stock rots. At what price per kg must he sell the rest to make an overall profit of 20%?","options":["₹58","₹48","₹60","₹50"],"answer":2,"explanation":"Cost = ₹4,000; required revenue = ₹4,800 from the 80 kg that remain, so ₹60 per kg. ₹48 ignores the loss of stock.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-23","question":"The marked price of an article is ₹300. A dealer gives a 10% discount and also one article free with every 8 bought. If he still gains 20%, his cost price per article is:","options":["₹200","₹180","₹240","₹225"],"answer":0,"explanation":"A customer pays 8 × 270 = ₹2,160 and gets 9 articles. 2,160 = 1.2 × 9 × CP, so CP = 2,160/10.8 = ₹200.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-24","question":"How many of the following statements are correct?\n1. Two articles sold at the same price, one at x% gain and the other at x% loss, always give an overall loss.\n2. Discount is always calculated on the cost price.\n3. Two successive discounts of 10% each equal a single discount of 20%.\n4. If the cost price of 12 articles equals the selling price of 10 articles, the gain is 20%.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"1 is true (loss of x²/100 %). 2 is false: discount is on the marked price. 3 is false: 0.9 × 0.9 = 0.81, a 19% discount. 4 is true: SP/CP = 12/10 = 1.2. Two statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-profit-loss-25","question":"A dishonest grocer cheats by 10% while buying and by 10% while selling, using false weights, and professes to sell at cost price. His gain percent is:","options":["20%","22 2/9 %","21%","19%"],"answer":1,"explanation":"Buying, he gets 1,100 g while paying for 1,000 g; selling, he gives 900 g while charging for 1,000 g. On 1,100 g bought for ₹1,000 he collects 1,100/900 × 1,000 = ₹1,222.2, a gain of 22 2/9 %. Simply adding 10 + 10 = 20% is wrong.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-26","question":"A sells a cycle to B at 20% profit, B sells it to C at 25% loss and C sells it to D at 60% profit. If D pays ₹1,728, A's cost price was:","options":["₹1,440","₹1,200","₹1,080","₹1,115"],"answer":1,"explanation":"Net factor = 1.2 × 0.75 × 1.6 = 1.44, so A's CP = 1,728/1.44 = ₹1,200. Adding the percentages (20 − 25 + 60 = 55%) and dividing by 1.55 gives the wrong ₹1,115.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-profit-loss-27","question":"A man sells a book for ₹24 and his profit percent is numerically equal to the cost price in rupees. The cost price is:","options":["₹20","₹24","₹16","₹12"],"answer":0,"explanation":"Let CP = x and profit = x%. SP = x + x²/100 = 24, so x² + 100x − 2,400 = 0, (x + 120)(x − 20) = 0, x = 20. Check: 20 + 20% of 20 = 24.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-28","question":"A merchant marks his goods 40% above cost. He sells one-third of the stock at the marked price, half of the remainder at a 20% discount and the rest at a 40% discount. His overall profit percent is:","options":["12%","20%","10%","16%"],"answer":0,"explanation":"Take 3 units costing ₹100 each (MP ₹140). Revenue = 140 + 140 × 0.8 + 140 × 0.6 = 140 + 112 + 84 = ₹336 against cost ₹300, profit 12%.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id": "quant-profit-loss-29", "question": "A man buys a pen for ₹80 and sells it for ₹92. What is his profit percent?", "options": ["12%", "15%", "13%", "12.5%"], "answer": 1, "explanation": "Profit = 92 − 80 = 12. Profit % = 12/80 × 100 = 15%. 13% wrongly divides by the selling price.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-profit-loss-30", "question": "By selling an article for ₹1,425 a trader loses 5%. At what price should he sell it to gain 10%?", "options": ["₹1,650", "₹1,567.50", "₹1,600", "₹1,575"], "answer": 0, "explanation": "CP = 1,425 ÷ 0.95 = 1,500. For 10% gain, SP = 1,500 × 1.1 = ₹1,650. ₹1,567.50 adds 10% to the loss-making SP instead of the CP.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-profit-loss-31", "question": "A trader marks his goods 30% above cost and allows a 10% discount. If his profit on an article is ₹68, what is its cost price?", "options": ["₹340", "₹500", "₹680", "₹400"], "answer": 3, "explanation": "SP = 1.3 × 0.9 × CP = 1.17 CP, so profit = 17% of CP = 68 and CP = ₹400. Taking profit as 30 − 10 = 20% gives ₹340.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-profit-loss-32", "question": "By selling 33 metres of cloth, a shopkeeper gains the selling price of 11 metres. What is his gain percent?", "options": ["33⅓%", "25%", "50%", "66⅔%"], "answer": 2, "explanation": "Profit = SP of 11 m, so CP of 33 m = SP of 33 m − SP of 11 m = SP of 22 m. Gain = 11/22 × 100 = 50%. 33⅓% divides by 33 instead of 22.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-profit-loss-33", "question": "A man buys two cows for ₹36,000. He sells one at a 20% profit and the other at a 10% loss, and on the whole neither gains nor loses. What did the cheaper cow cost?", "options": ["₹18,000", "₹12,000", "₹24,000", "₹15,000"], "answer": 1, "explanation": "Let the first cost x. 0.2x = 0.1(36,000 − x) → 0.3x = 3,600 → x = 12,000, the other ₹24,000. The cheaper cow (₹12,000) is the one sold at 20% profit.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-profit-loss-34", "question": "A shopkeeper marks an article 25% above cost and offers 'buy 4, get 1 free'. What is his overall profit or loss percent?", "options": ["No profit, no loss", "5% profit", "25% profit", "20% loss"], "answer": 0, "explanation": "For 5 articles costing 5C he receives the marked price of 4: 4 × 1.25C = 5C. Revenue equals cost, so no profit and no loss. The free item is a 20% discount, which cancels the 25% mark-up exactly.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-profit-loss-35", "question": "A dishonest dealer claims to sell at a 10% loss but gives only 750 g for every kilogram. What is his actual gain or loss percent?", "options": ["15% gain", "10% loss", "12.5% gain", "20% gain"], "answer": 3, "explanation": "Let 1 kg cost ₹100. He charges ₹90 (10% loss on 1 kg) but hands over 750 g, which cost him ₹75. Gain = 15/75 × 100 = 20%. 15% divides by 100 instead of 75.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-profit-loss-36", "question": "A sells a scooter to B at a 25% profit, B sells it to C at a 10% loss, and C sells it to D for ₹1,350, making a profit of ₹225. What was A's cost price?", "options": ["₹1,080", "₹1,200", "₹1,000", "₹960"], "answer": 2, "explanation": "C's cost = 1,350 − 225 = 1,125 = B's SP. B's cost = 1,125 ÷ 0.9 = 1,250 = A's SP. A's cost = 1,250 ÷ 1.25 = ₹1,000.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-profit-loss-37", "question": "A shopkeeper allows a 20% discount on the marked price and still gains 25% on an article costing ₹640. What is the marked price, and what would his profit percent be if he allowed only a 10% discount?", "options": ["₹1,000; 35%", "₹1,000; 40.625%", "₹960; 40.625%", "₹1,000; 45%"], "answer": 1, "explanation": "SP = 640 × 1.25 = 800 = 0.8 × MP, so MP = ₹1,000. With 10% off, SP = 900, profit = 260/640 × 100 = 40.625%. Adding 25% + 10% = 35% is the shortcut slip.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-profit-loss-38", "question": "A trader buys 40 kg of rice at ₹30 per kg and 80 kg at ₹36 per kg, mixes them and wants a 20% profit on the whole. At what price per kg must he sell the mixture?", "options": ["₹40.80", "₹39.60", "₹43.20", "₹40.00"], "answer": 0, "explanation": "Total cost = 40×30 + 80×36 = 1,200 + 2,880 = 4,080 for 120 kg, i.e. ₹34 per kg. With 20% profit: 34 × 1.2 = ₹40.80. ₹39.60 uses the simple average 33 instead of the weighted 34.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-profit-loss-39", "question": "An article is sold for ₹840 at a profit of 12%. What is its cost price?", "options": ["₹728", "₹739.20", "₹760", "₹750"], "answer": 3, "explanation": "CP = 840 ÷ 1.12 = ₹750. Taking 12% off ₹840 (₹739.20) is wrong because profit is a percent of CP.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-profit-loss-40", "question": "An article marked at ₹2,500 is sold for ₹2,125. What is the rate of discount?", "options": ["12.5%", "17.6%", "15%", "20%"], "answer": 2, "explanation": "Discount = ₹375, and discount is a percent of the marked price: 375/2,500 × 100 = 15%. 17.6% wrongly divides by the selling price.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-profit-loss-41", "question": "An article bought for ₹1,250 is sold for ₹1,100. What is the loss percent?", "options": ["15%", "12%", "10%", "13.64%"], "answer": 1, "explanation": "Loss = ₹150 and loss % = 150/1,250 × 100 = 12%. Dividing by the selling price gives 13.64%.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-profit-loss-42", "question": "A trader buys an article for ₹800, sells it at a 25% profit and charges 12% GST on the selling price. How much does the customer pay?", "options": ["₹1,096", "₹1,120", "₹1,140", "₹1,100"], "answer": 1, "explanation": "SP = 800 × 1.25 = ₹1,000; with 12% GST the customer pays 1,000 × 1.12 = ₹1,120. Adding 25% + 12% = 37% to ₹800 (₹1,096) ignores that GST is charged on the higher price.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-profit-loss-43", "question": "A shopkeeper makes a profit of 20% on the selling price. What is his profit as a percent of the cost price?", "options": ["24%", "25%", "16 2/3%", "20%"], "answer": 1, "explanation": "If SP = 100, profit = 20 and CP = 80, so profit on CP = 20/80 × 100 = 25%.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-44", "question": "By selling 36 oranges for ₹180 a vendor loses 10%. How many oranges must he sell for ₹180 to gain 8%?", "options": ["33", "30", "32", "28"], "answer": 1, "explanation": "SP of one orange = ₹5 = 0.9 × CP, so CP = ₹50/9. For an 8% gain, SP = 1.08 × 50/9 = ₹6, so he must sell 180 ÷ 6 = 30 oranges.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-45", "question": "After two successive discounts of 10% each, an article sells for ₹4,050. What is its marked price?", "options": ["₹5,200", "₹4,900", "₹5,000", "₹5,062.50"], "answer": 2, "explanation": "Two 10% discounts leave 0.9 × 0.9 = 0.81 of the MP, so MP = 4,050 ÷ 0.81 = ₹5,000. Treating them as one 20% discount gives ₹5,062.50.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-46", "question": "The profit made by selling an article for ₹920 is three times the loss incurred by selling it for ₹680. What is its cost price?", "options": ["₹740", "₹800", "₹760", "₹720"], "answer": 0, "explanation": "920 − C = 3(C − 680) gives 920 + 2,040 = 4C, so C = ₹740. Check: profit 180 = 3 × loss 60. ₹800 is the midpoint, which would need equal profit and loss.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-47", "question": "A man buys a TV and a fridge for ₹60,000 in all. He sells the TV at a 10% profit and the fridge at a 20% profit, earning ₹8,400 in all. What did the fridge cost?", "options": ["₹24,000", "₹36,000", "₹28,000", "₹30,000"], "answer": 0, "explanation": "0.1T + 0.2(60,000 − T) = 8,400 gives 12,000 − 0.1T = 8,400, so T = ₹36,000 and the fridge cost ₹24,000. ₹36,000 is the TV's price.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-profit-loss-48", "question": "Two successive discounts of x% and 20% are equivalent to a single discount of 32%. What is x?", "options": ["12", "15", "10", "12.5"], "answer": 1, "explanation": "(1 − x/100) × 0.8 = 0.68, so 1 − x/100 = 0.85 and x = 15. Subtracting 32 − 20 = 12 ignores that the second discount is on a reduced price.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-49", "question": "The cost price of 15 articles equals the marked price of 12 articles. If a discount of 10% is allowed, what is the profit percent?", "options": ["15%", "25%", "10%", "12.5%"], "answer": 3, "explanation": "MP = 15/12 × CP = 1.25 CP; SP = 0.9 × 1.25 = 1.125 CP, so profit = 12.5%. 25% is the markup before the discount.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-50", "question": "A merchant buys goods for ₹25,000. He sells one-fourth of them at a 10% loss. At what profit percent must he sell the rest to gain 20% on the whole?", "options": ["33 1/3%", "30%", "25%", "26 2/3%"], "answer": 1, "explanation": "Weighted: 0.25 × (−10) + 0.75p = 20, so 0.75p = 22.5 and p = 30%. In money: he needs ₹30,000, gets ₹5,625 from the first part, so ₹24,375 from ₹18,750 of goods, which is 30% profit.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-profit-loss-51", "question": "A shopkeeper gains 20% after allowing a 25% discount on the marked price. What would his profit percent be if he allowed only a 15% discount?", "options": ["32%", "30%", "34%", "36%"], "answer": 3, "explanation": "MP/CP = 1.2/0.75 = 1.6. With a 15% discount SP = 0.85 × 1.6 = 1.36 CP, a 36% profit. Adding the 10-point smaller discount to 20% (30%) ignores that it is 10% of the MP, not of the CP.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-profit-loss-52", "question": "A shopkeeper sells an article at a profit of 25%. If his cost price rises by 20% and he keeps the same selling price, what is his new profit percent?", "options": ["5%", "6 1/4%", "4%", "4 1/6%"], "answer": 3, "explanation": "Take CP = 100 and SP = 125. New CP = 120, profit = 5, so profit % = 5/120 × 100 = 4 1/6%. Subtracting 25 − 20 = 5% ignores the larger base.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-profit-loss-53", "question": "A shopkeeper gives a discount equal to the profit he makes, and the discount is 20% of the marked price. What is his profit percent?", "options": ["33 1/3%", "40%", "20%", "25%"], "answer": 0, "explanation": "Take MP = 100: discount = 20, SP = 80 and profit = 20, so CP = 60 and profit % = 20/60 = 33 1/3%.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-54", "question": "A man buys a used car for ₹3,60,000, spends ₹40,000 on repairs and sells it for ₹4,50,000 through a broker who charges 4% commission on the selling price. What is his profit percent?", "options": ["12.5%", "7.5%", "10%", "8%"], "answer": 3, "explanation": "Total cost = ₹4,00,000. He receives 4,50,000 − 18,000 = ₹4,32,000, so profit = ₹32,000 = 8%. 12.5% forgets the commission.", "difficulty": "hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-profit-loss-55", "question": "A shopkeeper marks an article 40% above cost, allows a 15% discount and then charges 10% GST on the discounted price. The customer pays ₹1,309. What is the cost price?", "options": ["₹1,000", "₹935", "₹1,100", "₹1,190"], "answer": 0, "explanation": "Customer price = CP × 1.4 × 0.85 × 1.1 = 1.309 CP = ₹1,309, so CP = ₹1,000.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-profit-loss-56", "question": "A store's monthly sales are ₹8 lakh and its gross margin is 25% of sales. Fixed expenses are ₹1.2 lakh a month. What is its net profit as a percent of the cost of goods sold?", "options": ["25%", "10%", "16 2/3%", "13 1/3%"], "answer": 3, "explanation": "Gross profit = 25% of 8 = ₹2 lakh, so cost of goods = ₹6 lakh. Net profit = 2 − 1.2 = ₹0.8 lakh = 0.8/6 = 13 1/3% of cost. 10% divides by sales instead.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-57", "question": "How many of the following statements are correct?\n1. A markup of 50% followed by a discount of 33 1/3% gives neither profit nor loss.\n2. 'Buy 2, get 1 free' is the same as a discount of 33 1/3%.\n3. Selling at cost price but using a 900 g weight for 1 kg gives a gain of 10%.\n4. A profit of 20% on the selling price equals a profit of 25% on the cost price.", "options": ["All four", "Only one", "Only three", "Only two"], "answer": 2, "explanation": "1: 1.5 × 2/3 = 1, true. 2: 1 item free in 3 is 1/3 off, true. 3: gain = 100/900 = 11 1/9%, false. 4: 20/80 = 25%, true.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-profit-loss-58", "question": "A shopkeeper buys three kinds of pens in the ratio 3 : 2 : 5 by number at ₹8, ₹12 and ₹16 each. He sells all of them at ₹16 each. What is his profit percent?", "options": ["20%", "25%", "33 1/3%", "28%"], "answer": 1, "explanation": "For 10 pens CP = 24 + 24 + 80 = ₹128 and SP = ₹160, so profit = 32/128 = 25%. Using the simple average price ₹12 gives 33 1/3%, ignoring the ratio.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-59", "question": "A manufacturer's cost is ₹10,000 and he wants a 26% profit after paying a 10% commission on the selling price to his agent. If he allows a 12.5% discount, what should the marked price be?", "options": ["₹16,000", "₹14,400", "₹15,750", "₹15,840"], "answer": 0, "explanation": "He needs ₹12,600 after commission, so SP = 12,600 ÷ 0.9 = ₹14,000, and MP = 14,000 ÷ 0.875 = ₹16,000. ₹15,840 adds 10% to ₹12,600 instead of dividing by 0.9.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-60", "question": "A man gains 25% on one article and loses 20% on another, and overall makes neither profit nor loss. If the two selling prices differ by ₹1,000, what was the total cost of the two articles?", "options": ["₹9,000", "₹10,000", "₹4,500", "₹8,000"], "answer": 0, "explanation": "0.25a = 0.2b gives a : b = 4 : 5; take a = 4k, b = 5k. SPs are 1.25 × 4k = 5k and 0.8 × 5k = 4k, which differ by k = 1,000. Total cost = 9k = ₹9,000.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-61", "question": "A shop sells 400 units a day at ₹50 each; each unit costs it ₹40. When the price is cut by 10%, daily sales rise by 50%. What happens to the shop's daily profit?", "options": ["It rises by 12.5%", "It falls by 10%", "It falls by 25%", "It rises by 35%"], "answer": 2, "explanation": "Before: 400 × (50 − 40) = ₹4,000. After: 600 × (45 − 40) = ₹3,000, a 25% fall. Revenue rises 35% (₹20,000 → ₹27,000), which is the trap.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-62", "question": "The cost of making an article is split among material, labour and overheads in the ratio 4 : 3 : 1, and it is sold at a 50% profit. Material cost rises by 25% and labour by 20%, overheads unchanged. If the selling price stays the same, what is the new profit percent?", "options": ["25%", "20%", "30%", "27.5%"], "answer": 0, "explanation": "Take cost = 8 (4 + 3 + 1) and SP = 12. New cost = 5 + 3.6 + 1 = 9.6, so profit = 2.4/9.6 = 25%. Subtracting the 20% cost rise from 50% gives 30%, a percent-of-different-bases slip.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-63", "question": "A sells an article to B at a profit of x%, and B sells it to C at a profit of 2x%. A's cost was ₹1,200 and C paid ₹2,016. What is x?", "options": ["22.5", "25", "15", "20"], "answer": 3, "explanation": "(1 + x/100)(1 + 2x/100) = 2,016/1,200 = 1.68. Trying x = 20: 1.2 × 1.4 = 1.68, so x = 20 (the other root is negative).", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-64", "question": "Assertion (A): A trader who marks his goods 25% above cost and allows a 20% discount makes neither profit nor loss.\nReason (R): Successive changes of +a% and −b% give a net change of (a − b − ab/100)%.", "options": ["A is true but R is false", "Both A and R are true, but R is not the correct explanation of A", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "By R: 25 − 20 − (25 × 20)/100 = 0, so A is true and follows from R.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-profit-loss-65", "question": "A man buys some oranges at 6 for ₹5 and an equal number at 4 for ₹5. He sells all of them at 5 for ₹5. What is his gain or loss percent?", "options": ["4 1/6% loss", "No profit no loss", "4% loss", "4% gain"], "answer": 2, "explanation": "Average CP per orange = (5/6 + 5/4)/2 = 25/24 rupee; SP = ₹1, so loss = (1/24)/(25/24) = 1/25 = 4%. Averaging the rates 6 and 4 to get 5 per ₹5 is the trap; 4 1/6% divides the loss by the SP.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-profit-loss-66", "question": "The cost prices of two articles are in the ratio 3 : 5. The first is sold at a 20% profit. At what profit or loss percent must the second be sold so that the overall profit is 5%?", "options": ["4% loss", "4% profit", "5% loss", "2.5% loss"], "answer": 0, "explanation": "Take CPs 3 and 5: total profit needed = 0.05 × 8 = 0.4, the first gives 0.6, so the second must lose 0.2 on 5, i.e. 4% loss.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-profit-loss-67", "question": "A shop offers two schemes on an item marked ₹1,000. Scheme 1: 30% off. Scheme 2: buy 3 get 1 free, plus 5% off the bill. For a customer who needs exactly 4 items, which scheme is cheaper and by how much?", "options": ["Scheme 2, by ₹50", "Scheme 1, by ₹150", "Scheme 1, by ₹50", "Both cost the same"], "answer": 2, "explanation": "Scheme 1: 4 × 700 = ₹2,800. Scheme 2: pay for 3 at 5% off = 3,000 × 0.95 = ₹2,850. Scheme 1 is cheaper by ₹50 (scheme 2 is an effective 28.75% discount).", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-profit-loss-68", "question": "A businessman buys a machine for ₹2,00,000. It earns him a net ₹30,000 a year for 3 years, after which he sells it at 30% below its cost price. What is his overall gain percent on the investment?", "options": ["30%", "15%", "10%", "45%"], "answer": 1, "explanation": "Total received = 3 × 30,000 + 0.7 × 2,00,000 = 90,000 + 1,40,000 = ₹2,30,000, a gain of ₹30,000 = 15%. 45% ignores the loss on resale.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-profit-loss-69","question":"A mobile cover bought for ₹150 is sold for ₹186. What is the profit percent?","options":["36%","24%","19.35%","20%"],"answer":1,"explanation":"Profit = ₹36 on a cost of ₹150: 36/150 × 100 = 24%. Dividing by the selling price gives 19.35%.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-profit-loss-70","question":"An article costing ₹2,400 is sold at a loss of 15%. What is its selling price?","options":["₹2,040","₹2,760","₹2,085","₹2,000"],"answer":0,"explanation":"SP = 85% of 2,400 = ₹2,040.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-71","question":"A farmer's cost of growing wheat is ₹1,940 per quintal and he sells it to the government at an MSP of ₹2,425 per quintal. What is his profit percent?","options":["20%","22.5%","48.5%","25%"],"answer":3,"explanation":"Profit = 485 on 1,940 = 25% (1,940 × 1.25 = 2,425). 485/2,425 = 20% wrongly takes profit on SP.","difficulty":"easy","source":"RRB NTPC · State PSC"},
  {"id":"quant-profit-loss-72","question":"On a phone with MRP ₹12,000, a store gives a 10% discount and the bank then gives 5% cashback on the amount paid. What is the effective discount on the MRP?","options":["15%","14%","14.5%","15.5%"],"answer":2,"explanation":"Net price = 0.9 × 0.95 = 0.855 of MRP, an effective discount of 14.5%. Successive discounts: 10 + 5 − (10 × 5)/100 = 14.5%.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-73","question":"A shopkeeper sells a pressure cooker for ₹2,016, which includes 12% GST, and makes a profit of 20% on his cost. What is his cost price?","options":["₹1,680","₹1,600","₹1,500","₹1,440"],"answer":2,"explanation":"Price before GST = 2,016 ÷ 1.12 = ₹1,800. Cost = 1,800 ÷ 1.2 = ₹1,500. GST is not part of the seller's profit.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-74","question":"A grocer mixes rice costing ₹32 per kg with rice costing ₹40 per kg in the ratio 3 : 1 and sells the mixture at ₹40.80 per kg. What is his profit percent?","options":["2%","20%","13.33%","25%"],"answer":1,"explanation":"Cost of the mix = (3 × 32 + 1 × 40)/4 = ₹34 per kg. Profit = 6.80/34 = 20%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-75","question":"A fruit seller buys 2 dozen bananas at ₹30 a dozen and 3 dozen at ₹40 a dozen. He sells all of them at ₹4.50 each. What is his profit percent?","options":["50%","35%","28.6%","45%"],"answer":0,"explanation":"Cost = 2 × 30 + 3 × 40 = ₹180 for 60 bananas. Sale = 60 × 4.50 = ₹270. Profit = 90/180 = 50%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-76","question":"A trader marks his goods 60% above cost and allows successive discounts of 25% and 10%. What is his profit percent?","options":["25%","12%","6%","8%"],"answer":3,"explanation":"SP = 1.6 × 0.75 × 0.9 = 1.08 of cost, a profit of 8%. 60 − 35 = 25% wrongly adds discounts and markup.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-77","question":"A dishonest shopkeeper uses a 960 g weight in place of 1 kg and openly sells at 4% below cost price. What is his actual result?","options":["4% gain","0.16% loss","8.33% gain","No profit, no loss"],"answer":3,"explanation":"For 960 g (cost 0.96 of a kg) he charges 96% of the price of 1 kg, which is exactly the cost of 960 g. So there is neither profit nor loss.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-78","question":"A retailer gets a 20% trade discount and then a 5% cash discount on the list price of goods. He sells them at the list price. What is his profit percent?","options":["25%","33.33%","31.58%","24%"],"answer":2,"explanation":"His cost = 0.8 × 0.95 = 0.76 of list price. Profit = 0.24/0.76 = 31.58%. 25% is the total discount, which is profit on SP, not on cost.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-79","question":"A home bakery has fixed costs of ₹45,000 a month. Each cake costs ₹150 to make and sells for ₹240. How many cakes must it sell in a month to earn a profit of ₹18,000?","options":["500","700","625","750"],"answer":1,"explanation":"Each cake contributes 240 − 150 = ₹90. Cakes needed = (45,000 + 18,000)/90 = 700. 500 cakes only break even.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-80","question":"A dealer sells a cooler to a retailer at 20% profit, and the retailer sells it at 25% profit. The customer pays ₹5,400 including 12.5% GST. What did the cooler cost the dealer?","options":["₹3,200","₹3,000","₹3,600","₹2,880"],"answer":0,"explanation":"Price before GST = 5,400 ÷ 1.125 = ₹4,800. Retailer's cost = 4,800 ÷ 1.25 = ₹3,840. Dealer's cost = 3,840 ÷ 1.2 = ₹3,200.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-81","question":"An article is sold at a 20% profit. If both its cost price and selling price were ₹60 more, the profit would be 15%. What is the cost price?","options":["₹180","₹240","₹200","₹150"],"answer":0,"explanation":"(1.2c + 60)/(c + 60) = 1.15 gives 1.2c + 60 = 1.15c + 69, so 0.05c = 9 and c = ₹180. Profit stays ₹36, now on ₹240 = 15%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-profit-loss-82","question":"A manufacturer sells to a wholesaler at 10% profit, the wholesaler to a retailer at 15% profit and the retailer to a customer at 20% profit. If the customer pays ₹30,360, what was the manufacturing cost?","options":["₹20,240","₹22,000","₹18,975","₹20,000"],"answer":3,"explanation":"Chain multiplier = 1.1 × 1.15 × 1.2 = 1.518. Cost = 30,360 ÷ 1.518 = ₹20,000. Adding 10 + 15 + 20 = 45% gives the wrong ₹20,938.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-83","question":"A shopkeeper sells 3/5 of his stock at a 20% profit and the rest at a loss of x%. Overall he makes a 4% profit. What is x?","options":["16","24","20","10"],"answer":2,"explanation":"0.6 × 20 − 0.4x = 4 gives 0.4x = 8 and x = 20.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-84","question":"A trader wants a 14% profit after giving successive discounts of 10% and 5% on the marked price. By what percent above cost must he mark his goods?","options":["29%","33.33%","30%","31.5%"],"answer":1,"explanation":"MP × 0.9 × 0.95 = 1.14 × CP, so MP = 1.14/0.855 = 4/3 of CP, i.e. 33.33% above cost. Adding 14 + 15 = 29% is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-profit-loss-85","question":"A vendor buys 80 kg of tomatoes at ₹30 per kg. 10% of them get damaged and are sold at half the cost price. At what price per kg must he sell the rest to make a 25% profit overall?","options":["₹37.50","₹40","₹41.67","₹38"],"answer":1,"explanation":"Target revenue = 1.25 × 2,400 = ₹3,000. Damaged 8 kg fetch 8 × 15 = ₹120. The other 72 kg must bring ₹2,880, i.e. ₹40 per kg.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-86","question":"Ravi buys a cycle for ₹5,000 and sells it to Mohan at a 10% profit. Later Mohan sells it back to Ravi at a 10% loss. What is Ravi's overall gain?","options":["₹550","₹500","₹0","₹50"],"answer":0,"explanation":"Ravi receives ₹5,500 and later pays 90% of 5,500 = ₹4,950, keeping the cycle. His gain = 5,500 − 4,950 = ₹550.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-87","question":"On every purchase of 15 notebooks, a shop gives a discount equal to the marked price of 3 notebooks and still makes a 12% profit. By what percent above cost are the notebooks marked?","options":["32%","35%","30%","40%"],"answer":3,"explanation":"The discount is 3/15 = 20% of the marked price. 0.8 × MP = 1.12 × CP gives MP = 1.4 × CP, i.e. 40% above cost.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-88","question":"An online seller buys a product for ₹500. The platform keeps 20% of the selling price as fee, and the seller also pays ₹50 for delivery. At what price must he list it to earn 30% profit on his cost?","options":["₹830","₹812.50","₹875","₹840"],"answer":2,"explanation":"He must keep 650 + 50 = ₹700 after the fee, which is 80% of the price. Price = 700 ÷ 0.8 = ₹875.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-89","question":"A shopkeeper buys 120 pens for the marked price of 100 pens and sells them at a 1% discount on the marked price. What is his profit percent?","options":["20%","19%","18.8%","17.6%"],"answer":2,"explanation":"Cost of each pen = 100/120 of MP; selling price = 0.99 MP. Profit = 0.99 × 1.2 − 1 = 0.188, i.e. 18.8%.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-90","question":"A wholesaler gives 'buy 5, get 1 free' to a retailer at the marked price. The retailer sells to customers at the same marked price with 'buy 3, get 1 free'. What is the retailer's result?","options":["8.33% loss","10% loss","No profit, no loss","10% gain"],"answer":1,"explanation":"Cost per item = 5/6 of MP; revenue per item = 3/4 of MP. Loss = (5/6 − 3/4) ÷ 5/6 = (1/12) × (6/5) = 10%.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-91","question":"A sells goods to B at a 25% profit. B spends 5% of his purchase price on transport and sells to C at a 20% profit on his total cost. If C pays ₹3,150, what did the goods cost A?","options":["₹2,000","₹2,100","₹1,890","₹2,250"],"answer":0,"explanation":"Multiplier = 1.25 × 1.05 × 1.2 = 1.575. A's cost = 3,150 ÷ 1.575 = ₹2,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-92","question":"In a factory, raw material makes up 60% of the cost of a product and labour the remaining 40%. Raw material prices rise by 25% and wages by 10%. By what percent must the selling price rise to keep the same profit percent?","options":["17.5%","35%","20%","19%"],"answer":3,"explanation":"New cost = 0.6 × 1.25 + 0.4 × 1.10 = 1.19 of the old. The same profit percent needs the SP to rise by 19% too. 17.5% averages the rises without weights.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-93","question":"A shopkeeper earns a profit of 20% on the selling price when he gives a 20% discount on the marked price. What would his profit percent on cost be if he sold at the marked price?","options":["50%","40%","45%","56.25%"],"answer":3,"explanation":"Take MP = 100: SP = 80 and cost = 80 − 20% of 80 = 64. At MP, profit = 36/64 = 56.25%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-profit-loss-94","question":"A sells goods to B at a 20% profit and B sells them to C at a 10% profit. Had A sold at a 30% profit and B at a 5% profit, C would have paid ₹180 more. What was A's cost price?","options":["₹3,600","₹4,500","₹4,000","₹5,000"],"answer":2,"explanation":"Multipliers: 1.2 × 1.1 = 1.32 and 1.3 × 1.05 = 1.365. The difference 0.045 of A's cost = ₹180, so the cost = ₹4,000.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-95","question":"If the selling price of an article is doubled, the profit triples. What is the profit percent?","options":["50%","100%","200%","150%"],"answer":1,"explanation":"2S − C = 3(S − C) gives S = 2C, so the profit is 100%.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-96","question":"A jacket marked ₹1,500 is sold at a 12% discount. What is its selling price?","options":["₹1,320","₹1,380","₹1,180","₹1,488"],"answer":0,"explanation":"SP = 88% of 1,500 = ₹1,320.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-profit-loss-97","question":"A shoe with MRP ₹999 carries 'flat 30% off' plus 'extra 10% off on the app'. How much does an app buyer pay?","options":["₹599.40","₹639.36","₹699.30","₹629.37"],"answer":3,"explanation":"999 × 0.7 × 0.9 = 999 × 0.63 = ₹629.37. Treating it as 40% off gives ₹599.40.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-profit-loss-98","question":"A tailor buys cloth at ₹180 per metre. A shirt uses 1.6 m of cloth and ₹120 of stitching cost. If he sells each shirt for ₹510, what is his profit percent?","options":["20%","27.5%","41.7%","25%"],"answer":3,"explanation":"Cost per shirt = 1.6 × 180 + 120 = ₹408. Profit = 102/408 = 25%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-99","question":"A dhaba's thali costs ₹160 to make and is priced at ₹250. On each of the 5 weekdays it gives 20% off and sells 120 thalis; on each of the 2 weekend days it charges full price and sells 200 thalis. What is its weekly profit?","options":["₹72,000","₹54,000","₹60,000","₹66,000"],"answer":2,"explanation":"Weekday margin = 200 − 160 = ₹40 on 600 thalis = ₹24,000. Weekend margin = ₹90 on 400 thalis = ₹36,000. Total ₹60,000.","difficulty":"hard","source":"IBPS PO · SBI Clerk"},
  {"id":"quant-profit-loss-100","question":"Two shops sell the same item at the same marked price. Shop A gives a 30% discount, while Shop B gives successive discounts of 16% and 14%. If the item is ₹56 cheaper at Shop A, what is its marked price?","options":["₹2,800","₹2,500","₹2,240","₹2,000"],"answer":1,"explanation":"Shop B's single discount = 16 + 14 − 2.24 = 27.76%. Difference = 2.24% of MP = ₹56, so MP = ₹2,500.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-101","question":"A dealer buys two machines for ₹25,000 in all. He sells the first at a 15% profit and the second at a 25% profit, earning ₹4,750 in total profit. What did the first machine cost?","options":["₹15,000","₹10,000","₹12,500","₹17,500"],"answer":0,"explanation":"Overall profit = 4,750/25,000 = 19%. Alligation: (25 − 19) : (19 − 15) = 6 : 4 = 3 : 2. First machine = 3/5 × 25,000 = ₹15,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-102","question":"If an article is sold at a profit of 37.5%, what is the ratio of its selling price to its cost price?","options":["11 : 8","8 : 11","3 : 8","5 : 8"],"answer":0,"explanation":"37.5% = 3/8, so SP = CP × (1 + 3/8) = 11/8 of CP. SP : CP = 11 : 8.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-103","question":"A trader makes a profit of 25% on the selling price by selling an article for ₹1,600. At what price should he sell it to make a 20% profit on cost?","options":["₹1,536","₹1,600","₹1,500","₹1,440"],"answer":3,"explanation":"Cost = 75% of 1,600 = ₹1,200. For 20% on cost, SP = 1,200 × 1.2 = ₹1,440.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-104","question":"An electronics dealer buys at 12.5% below MRP and sells at 4% below MRP. What is his profit percent, approximately?","options":["8.5%","12.5%","9.7%","8.9%"],"answer":2,"explanation":"Profit = 0.96/0.875 − 1 = 0.0971, about 9.7%. 12.5 − 4 = 8.5% is profit as a share of MRP, not of cost.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-105","question":"Selling an article for ₹960 gives a loss of x%, while selling it for ₹1,410 gives a profit of x%. What is the cost price?","options":["₹1,200","₹1,185","₹1,150","₹1,175"],"answer":1,"explanation":"Equal percentages on the same cost mean equal amounts, so the cost is midway: (960 + 1,410)/2 = ₹1,185.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-profit-loss-106","question":"A shopkeeper buys 80 kg of sugar at ₹42 per kg. He sells 30 kg at a 15% profit and 30 kg at a 10% loss. At what price per kg must he sell the remaining 20 kg to make a 10% profit overall?","options":["₹52.50","₹55.65","₹50.40","₹57.75"],"answer":1,"explanation":"Target = 1.1 × 3,360 = ₹3,696. Sales so far = 30 × 48.30 + 30 × 37.80 = ₹2,583. The last 20 kg must bring ₹1,113, i.e. ₹55.65 per kg.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-107","question":"An article is sold for ₹3,600 and the profit is one-fifth of the selling price. What is the profit percent on cost?","options":["25%","20%","16.67%","30%"],"answer":0,"explanation":"Profit = 3,600/5 = ₹720 and cost = ₹2,880. Profit on cost = 720/2,880 = 25%. A 1/5 share of SP is 1/4 of cost.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-108","question":"A shopkeeper buys eggs at ₹60 a dozen. One egg in every dozen breaks, and he sells the rest at ₹6 each. What is his profit percent?","options":["20%","8.33%","12.5%","10%"],"answer":3,"explanation":"Per dozen: cost ₹60, sale = 11 × 6 = ₹66. Profit = 6/60 = 10%.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-profit-loss-109","question":"A trader's price of a fan is ₹1,770 including 18% GST, which he passes on to the government. If the fan cost him ₹1,200 before GST, what is his profit percent?","options":["47.5%","20%","25%","22.5%"],"answer":2,"explanation":"His price before GST = 1,770 ÷ 1.18 = ₹1,500. Profit = 300/1,200 = 25%. Comparing 1,770 with 1,200 (47.5%) wrongly counts the tax as profit.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-110","question":"A man sells a scooter costing ₹50,000 at a 20% loss. With the money he buys a motorbike and sells it at a 20% profit. What is his overall result?","options":["No profit, no loss","₹2,000 gain","₹2,000 loss","₹4,000 loss"],"answer":2,"explanation":"He gets ₹40,000, which grows by 20% to ₹48,000. Compared with ₹50,000 he is ₹2,000 down: the 20% profit is on a smaller base.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-profit-loss-111","question":"A shopkeeper marks his goods 40% above cost and allows a discount of d%, still making a 19% profit. What would happen if he allowed a discount of 2d%?","options":["4% profit","2% loss","No profit, no loss","2% profit"],"answer":1,"explanation":"1.4(1 − d) = 1.19 gives d = 15%. With 30% off, SP = 1.4 × 0.7 = 0.98 of cost, a 2% loss.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-profit-loss-112","question":"A sari costs a merchant ₹2,000. He wants a 20% profit after allowing a 20% discount and paying his agent a 4% commission on the selling price. What should the marked price be?","options":["₹3,125","₹3,000","₹3,250","₹3,200"],"answer":0,"explanation":"He must keep ₹2,400 after commission, so SP = 2,400 ÷ 0.96 = ₹2,500. MP = 2,500 ÷ 0.8 = ₹3,125.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-113","question":"A dealer mixes tea costing ₹200 per kg with tea costing ₹300 per kg and sells the blend at ₹330 per kg, making a 20% profit. In what ratio did he mix the two teas?","options":["3 : 1","2 : 3","1 : 2","1 : 3"],"answer":3,"explanation":"Cost of the blend = 330 ÷ 1.2 = ₹275. Alligation: (300 − 275) : (275 − 200) = 25 : 75 = 1 : 3 (cheaper : dearer).","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-114","question":"If a shopkeeper gives a 25% discount on the marked price he loses ₹30, but if he gives a 10% discount he gains ₹60. What is the cost price?","options":["₹450","₹500","₹420","₹480"],"answer":3,"explanation":"The two selling prices differ by 15% of MP = 30 + 60 = ₹90, so MP = ₹600. Cost = 0.75 × 600 + 30 = ₹480.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-115","question":"A wholesaler sells on credit at a 15% profit, but 5% of the sales amount is never recovered. What is his actual profit percent?","options":["10%","9.5%","9.25%","8.75%"],"answer":2,"explanation":"Money received = 1.15 × 0.95 = 1.0925 of cost, a 9.25% profit. 15 − 5 = 10% ignores that the bad debt is 5% of the larger sales figure.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-116","question":"A dairy buys milk at ₹48 a litre, adds water equal to 20% of the milk's volume and sells the mixture at ₹54 a litre. What is its profit percent?","options":["12.5%","35%","32.5%","30%"],"answer":1,"explanation":"1 L of milk (₹48) becomes 1.2 L, sold for 1.2 × 54 = ₹64.80. Profit = 16.80/48 = 35%. Multipliers: 1.2 × 54/48 = 1.35.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-profit-loss-117","question":"A manufacturer makes a cooler for ₹800 and marks it 50% above cost. He gives a 20% trade discount to a retailer, who sells it at the manufacturer's marked price plus 10% GST. What is the retailer's profit percent?","options":["25%","37.5%","50%","20%"],"answer":0,"explanation":"MP = ₹1,200, so the retailer pays ₹960. He keeps ₹1,200 (the GST goes to the government). Profit = 240/960 = 25%.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-118","question":"An article costing ₹1,200 is sold at a profit of ₹150. What is the profit percent?","options":["12.5%","15%","11.11%","10%"],"answer":0,"explanation":"150/1,200 × 100 = 12.5%.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-profit-loss-119","question":"A pair of earphones bought for ₹750 is sold for ₹840. What is the profit percent?","options":["10.71%","9%","15%","12%"],"answer":3,"explanation":"Profit = ₹90 on a cost of ₹750: 90/750 × 100 = 12%.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-profit-loss-120","question":"A trader sells a lamp for ₹1,092 at a profit of 5%. What did it cost him?","options":["₹1,037.40","₹1,050","₹1,040","₹1,146.60"],"answer":2,"explanation":"Cost = 1,092 ÷ 1.05 = ₹1,040. Taking 5% off the selling price (₹1,037.40) uses the wrong base.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-121","question":"The marked price of a mixer is ₹840, which is 40% above its cost. If it is sold at a 15% discount, what is the profit percent?","options":["25%","19%","21%","15%"],"answer":1,"explanation":"Cost = 840 ÷ 1.4 = ₹600; SP = 0.85 × 840 = ₹714. Profit = 114/600 = 19% (check: 1.4 × 0.85 = 1.19).","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-profit-loss-122","question":"A store gives one shirt free with every four shirts bought. What is the effective discount?","options":["20%","25%","16.67%","80%"],"answer":0,"explanation":"The customer gets 5 shirts for the price of 4, so he saves 1 out of 5 = 20%. 25% wrongly divides by the 4 paid for.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-profit-loss-123","question":"The cost price and selling price of an article are in the ratio 4 : 5. If the cost rises by 25% and the selling price by 10%, what is the new profit percent?","options":["10%","15%","12.5%","5%"],"answer":0,"explanation":"New CP = 4 × 1.25 = 5 and new SP = 5 × 1.1 = 5.5. Profit = 0.5/5 = 10%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-124","question":"A shopkeeper makes a 5% profit even after allowing a 30% discount. By what percent above cost is the article marked?","options":["35%","45%","40%","50%"],"answer":3,"explanation":"MP × 0.7 = 1.05 × CP, so MP = 1.5 × CP, i.e. 50% above cost. 30 + 5 = 35% is the trap.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-profit-loss-125","question":"A trader marks his goods 35% above cost. What discount must he give so that he makes a profit of 8%?","options":["27%","25%","20%","18%"],"answer":2,"explanation":"1.35 × (1 − d) = 1.08 gives 1 − d = 0.8, so d = 20%. 35 − 8 = 27% subtracts on the wrong base.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-126","question":"A refrigerator is sold at a 12% loss. Had it been sold for ₹3,000 more, there would have been an 8% profit. At what price should it be sold to make a 20% profit?","options":["₹15,000","₹18,000","₹16,200","₹19,500"],"answer":1,"explanation":"The swing from −12% to +8% is 20% of cost = ₹3,000, so cost = ₹15,000. For 20% profit, SP = ₹18,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-127","question":"A retailer buys a smartphone at 20% below its MRP and sells it at 8% below MRP, making a profit of ₹1,800. What is the MRP?","options":["₹22,500","₹15,000","₹9,000","₹12,000"],"answer":1,"explanation":"Profit = (92 − 80)% of MRP = 12% of MRP = ₹1,800, so MRP = ₹15,000.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-profit-loss-128","question":"A sells an article to B at a 20% profit and B sells it to C at a further 20% profit. C pays ₹440 more than A's cost price. What was A's cost price?","options":["₹1,000","₹1,100","₹2,200","₹880"],"answer":0,"explanation":"C pays 1.2 × 1.2 = 1.44 of A's cost, i.e. 44% more. 44% = ₹440, so A's cost = ₹1,000. Using 40% gives ₹1,100.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-129","question":"A shoe has an MRP of ₹2,100 including 5% GST. The retailer gives a 10% discount on the MRP (GST remains 5% of the discounted price, included). His cost before GST is ₹1,500. What is his profit percent?","options":["26%","12.5%","40%","20%"],"answer":3,"explanation":"Customer pays 0.9 × 2,100 = ₹1,890, of which the retailer keeps 1,890 ÷ 1.05 = ₹1,800. Profit = 300/1,500 = 20%.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-profit-loss-130","question":"A trader loses 5% when he sells an article at a certain price. If he raises that price by 12%, what is his result?","options":["7% profit","6% profit","6.4% profit","5.4% profit"],"answer":2,"explanation":"New SP = 0.95 × 1.12 = 1.064 of cost, a profit of 6.4%. 12 − 5 = 7% ignores that the 12% is on the lower selling price.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-profit-loss-131","question":"A furniture dealer sells a sofa at a 15% profit. Had he sold it for ₹1,890 more, his profit would have been 22%. At what price must he sell it to make a 30% profit?","options":["₹27,000","₹31,050","₹35,100","₹34,500"],"answer":2,"explanation":"The extra 7% of cost = ₹1,890, so cost = ₹27,000. For 30% profit, SP = 1.3 × 27,000 = ₹35,100.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-132","question":"A shopkeeper wanted to mark his goods 60% above cost so as to gain 20% after a 25% discount. By mistake he marked them only 25% above cost but still gave the 25% discount. What was his result?","options":["No profit, no loss","6.25% loss","5% loss","6.25% profit"],"answer":1,"explanation":"SP = 1.25 × 0.75 = 0.9375 of cost, a loss of 6.25%. A markup and a discount of the same percent always end in a loss.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-133","question":"Article A costs 25% more than article B. A is sold at a 20% loss and B at a 35% profit, and together they fetch ₹23,500. What is the overall profit?","options":["₹1,000","₹1,250","₹750","₹1,500"],"answer":0,"explanation":"With B = b: SP = 1.25b × 0.8 + 1.35b = 2.35b = 23,500, so b = ₹10,000. Total cost = 2.25b = ₹22,500, profit = ₹1,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-134","question":"A merchant sells one-third of his grain at a 10% profit, half of the remainder at a 20% profit and the rest at a 25% loss. What is his overall result?","options":["5% profit","1.67% loss","No profit, no loss","1.67% profit"],"answer":3,"explanation":"Each part is one-third of the stock, so the overall result = (10 + 20 − 25)/3 = 5/3 ≈ 1.67% profit.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-135","question":"Article X costs ₹2,000 more than article Y. X is sold at a 15% profit and Y at a 10% loss, and X fetches ₹3,600 more than Y. What is the cost of Y?","options":["₹7,200","₹5,000","₹4,800","₹5,200"],"answer":3,"explanation":"1.15(y + 2,000) − 0.9y = 3,600 gives 0.25y + 2,300 = 3,600, so y = ₹5,200.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-profit-loss-136","question":"Two successive discounts of x% and (x − 10)% are equivalent to a single discount of 44%. What is x?","options":["27","34","30","25"],"answer":2,"explanation":"(1 − x/100)(1.1 − x/100) = 0.56. Trying x = 30: 0.7 × 0.8 = 0.56. So x = 30.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-profit-loss-137","question":"A builder buys a plot for ₹48 lakh and pays 5% stamp duty on it, then spends ₹29.6 lakh on construction. He sells the house for ₹90 lakh and pays a 2% brokerage on the sale. What is his profit percent?","options":["12.5%","10.25%","8.2%","12.75%"],"answer":1,"explanation":"Cost = 48 + 2.4 + 29.6 = ₹80 lakh. Net receipt = 90 × 0.98 = ₹88.2 lakh. Profit = 8.2/80 = 10.25%.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-138","question":"A shopkeeper gains 6.25% by selling a geyser for ₹1,904, which includes 12% GST. What price including GST should he charge to gain 25%?","options":["₹2,240","₹2,000","₹2,380","₹2,256"],"answer":0,"explanation":"Pre-GST price = 1,904 ÷ 1.12 = ₹1,700, so cost = 1,700 ÷ 1.0625 = ₹1,600. For 25% gain: 2,000 + 12% GST = ₹2,240.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-139","question":"A company sells a product to a distributor for ₹720. The distributor's margin is 10% of his selling price, and the retailer's margin is 20% of the MRP at which he sells. What is the MRP?","options":["₹1,000","₹950.40","₹1,036.80","₹960"],"answer":0,"explanation":"Margins on selling price: distributor sells at 720 ÷ 0.9 = ₹800, retailer at 800 ÷ 0.8 = ₹1,000. Treating margins as markups on cost gives ₹950.40.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-profit-loss-140","question":"A person buys two items for ₹1,000 in all. He sells the first at a 20% gain and the second at a 12% loss, and gets back exactly ₹1,000. What did the first item cost?","options":["₹625","₹400","₹350","₹375"],"answer":3,"explanation":"Gain on the first must equal loss on the second: 0.2a = 0.12(1,000 − a), so 0.32a = 120 and a = ₹375.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-profit-loss-141","question":"A factory makes 500 units a day at ₹120 each. 4% are defective and sold as scrap at ₹30 each; the rest sell at ₹150 each. What is the daily profit?","options":["₹15,000","₹12,000","₹12,600","₹13,200"],"answer":2,"explanation":"Revenue = 480 × 150 + 20 × 30 = ₹72,600. Cost = 500 × 120 = ₹60,000. Profit = ₹12,600.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"quant-profit-loss-142","question":"A man sells 20% of his stock at a 25% profit. At what profit percent must he sell the rest to make a 30% profit overall?","options":["35%","31.25%","32.5%","30%"],"answer":1,"explanation":"0.2 × 25 + 0.8 × x = 30 gives 0.8x = 25 and x = 31.25%.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-profit-loss-143","question":"A sells an article to B at a profit of p%, and B sells it to C at a loss of p%. C pays 4% less than A's cost. What is p?","options":["4","20","16","25"],"answer":1,"explanation":"(1 + p/100)(1 − p/100) = 0.96, so p²/10,000 = 0.04 and p = 20.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
];

export default questions;
